//! Optional local legacy-office conversion. This module never edits a note or
//! calls an existing desktop Office session. Every run owns a new working
//! directory and returns the exact original, intermediate and generated bytes.
//! Ordinary DOCX conversion has no dependency on this module's host software.
use crate::owned_process::{Command, Stdio};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    fs::{self, OpenOptions},
    io::{Read, Write},
    path::{Path, PathBuf},
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    time::Duration,
};

const MAX_BYTES: usize = 64 * 1024 * 1024;
const TIMEOUT: Duration = Duration::from_secs(90);
const OLE_MAGIC: &[u8] = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1";

pub(crate) struct ConversionLocation {
    pub(crate) root: PathBuf,
    pub(crate) request_id: String,
}
/// Keep private actor stages in their original namespace, but avoid expanding
/// that namespace into the native application's working/profile paths. The
/// opaque ID retains 122 SHA-256 bits after UUID version/variant bits are set.
pub(crate) fn scoped_location(
    base: &Path,
    deployment: &str,
    library_root: &Path,
    actor: &str,
    actor_epoch: u64,
    user_operation_id: &str,
    purpose: &str,
) -> Result<ConversionLocation, LegacyError> {
    let id = uuid::Uuid::parse_str(user_operation_id)
        .map_err(|_| error("requestId", "旧格式转换需要规范 UUIDv4 操作标识"))?;
    if !base.is_absolute()
        || id.to_string() != user_operation_id
        || id.get_version() != Some(uuid::Version::Random)
        || !matches!(purpose, "export" | "import")
    {
        return Err(error("conversionScope", "外部转换目录或操作作用域无效"));
    }
    let scope = serde_json::json!({"schemaVersion":1,"deployment":deployment,"libraryRoot":library_root,"actor":actor,"actorEpoch":actor_epoch,"userOperationId":user_operation_id,"purpose":purpose});
    let hash = Sha256::digest(scope.to_string().as_bytes());
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&hash[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Ok(ConversionLocation {
        root: base.join("runs"),
        request_id: uuid::Uuid::from_bytes(bytes).to_string(),
    })
}

fn execution_path_budget(workspace: &Path, backend: &str) -> Result<(), LegacyError> {
    #[cfg(windows)]
    {
        use std::os::windows::ffi::OsStrExt;
        let units: Vec<u16> = workspace.as_os_str().encode_wide().collect();
        let prefix: Vec<u16> = r"\\?\".encode_utf16().collect();
        let unc: Vec<u16> = r"\\?\UNC\".encode_utf16().collect();
        let length = if units.starts_with(&unc) {
            units.len() - unc.len() + 2
        } else if units.starts_with(&prefix) {
            units.len() - prefix.len()
        } else {
            units.len()
        };
        // CreateProcess rejects a >MAX_PATH current directory even with a
        // verbatim prefix. This installed Writer also crashes in first-profile
        // initialization at 191 native units; 120/125/127-unit owned workspaces
        // were verified. Use that conservative envelope, not an inferred claim
        // that every internal Writer file supports Windows long paths.
        let limit = if backend == "libreoffice" { 128 } else { 240 };
        if length > limit {
            return Err(error(
                "executionPathTooLong",
                format!(
                    "Server外部转换工作路径超过当前Windows后端的{limit} UTF-16字符预算；准确原件保留，未启动外部软件。请缩短独立data-dir后显式新建操作。"
                ),
            ));
        }
    }
    #[cfg(not(windows))]
    {
        let _ = (workspace, backend);
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub(crate) enum Direction {
    DocToDocx,
    DocxToDoc,
    WpsToDocx,
    DocxToWps,
}
impl Direction {
    fn extensions(self) -> (&'static str, &'static str) {
        match self {
            Self::DocToDocx => ("doc", "docx"),
            Self::DocxToDoc => ("docx", "doc"),
            Self::WpsToDocx => ("wps", "docx"),
            Self::DocxToWps => ("docx", "wps"),
        }
    }
    fn is_import(self) -> bool {
        matches!(self, Self::DocToDocx | Self::WpsToDocx)
    }
    fn involves_native_wps(self) -> bool {
        matches!(self, Self::WpsToDocx | Self::DocxToWps)
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct DirectionCapability {
    pub(crate) direction: Direction,
    pub(crate) available: bool,
    /// This is deliberately false: discovering a software version or a filter
    /// is not a real-host content/review round-trip acceptance result.
    pub(crate) content_roundtrip_verified: bool,
    pub(crate) reason: String,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct BackendCapability {
    pub(crate) id: String,
    pub(crate) version: Option<String>,
    pub(crate) directions: Vec<DirectionCapability>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct LegacyCapabilities {
    pub(crate) backends: Vec<BackendCapability>,
    pub(crate) ordinary_docx_requires_office: bool,
}

#[derive(Debug, Clone)]
pub(crate) struct ConversionRequest {
    /// "libreoffice" or "configured". Not an arbitrary executable or command.
    pub(crate) backend: String,
    pub(crate) direction: Direction,
    pub(crate) bytes: Vec<u8>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct Artifact {
    pub(crate) filename: String,
    pub(crate) sha256: String,
    pub(crate) length: usize,
    /// Retained inside this run's owned directory; never an original user path.
    pub(crate) retained_path: PathBuf,
    #[serde(skip)]
    pub(crate) bytes: Vec<u8>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct FeatureReport {
    pub(crate) feature: String,
    pub(crate) before: String,
    pub(crate) after: String,
    pub(crate) message: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct ConversionResult {
    pub(crate) request_id: String,
    /// succeeded / failed / cancelled / unknown / unavailable. A cancelled or
    /// unknown result never exposes a late output as a completed artifact.
    pub(crate) status: String,
    pub(crate) code: String,
    pub(crate) message: String,
    pub(crate) backend: String,
    pub(crate) backend_version: Option<String>,
    pub(crate) direction: Direction,
    pub(crate) original: Artifact,
    pub(crate) intermediate_docx: Option<Artifact>,
    pub(crate) generated: Option<Artifact>,
    pub(crate) features: Vec<FeatureReport>,
    pub(crate) workspace: PathBuf,
    pub(crate) diagnostic: String,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct ConversionLoss {
    pub(crate) code: String,
    pub(crate) message: String,
    pub(crate) location: Option<String>,
}
impl ConversionResult {
    pub(crate) fn losses(&self) -> Vec<ConversionLoss> {
        self.features
            .iter()
            .filter(|feature| feature.after != "preserved")
            .map(|feature| ConversionLoss {
                code: format!("legacyOffice_{}Unverified", feature.feature),
                message: feature.message.clone(),
                location: Some(feature.feature.clone()),
            })
            .collect()
    }

    /// Safe for a local UI/job preview: exact digests, direction and staged
    /// loss disclosures, with no absolute host paths or artifact bytes.
    pub(crate) fn metadata(&self) -> serde_json::Value {
        let (input, output) = self.direction.extensions();
        let describe = |artifact: &Artifact| {
            serde_json::json!({
                "filename": artifact.filename, "length": artifact.length, "sha256": artifact.sha256,
            })
        };
        serde_json::json!({
            "requestId": self.request_id, "status": self.status, "code": self.code,
            "message": self.message, "backend": self.backend, "backendVersion": self.backend_version,
            "direction": self.direction, "inputFormat": input, "outputFormat": output,
            "contentType": match output { "doc" => "application/msword", "docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document", _ => "application/octet-stream" },
            "stage": if self.direction.is_import() { "legacyToDocx" } else { "docxToLegacy" },
            "original": describe(&self.original),
            "intermediateDocx": self.intermediate_docx.as_ref().map(describe),
            "generated": self.generated.as_ref().map(describe),
            "features": self.features, "losses": self.losses(),
            "requiresLossConfirmation": self.status == "succeeded" && self.generated.is_some() && !self.losses().is_empty(),
            "contentRoundtripVerified": false,
            "nativeConversionRequiresSeparateReport": true,
        })
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct LegacyError {
    pub(crate) code: String,
    pub(crate) message: String,
}
impl std::fmt::Display for LegacyError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}
impl std::error::Error for LegacyError {}
fn error(code: &str, message: impl Into<String>) -> LegacyError {
    LegacyError {
        code: code.into(),
        message: message.into(),
    }
}

/// Operator-owned optional adapter configuration. The environment is read by
/// the local process, never accepted from an HTTP request. A native Kingsoft
/// WPS adapter must explicitly declare that format; a Works filter is invalid.
#[derive(Clone, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct AdapterConfig {
    schema_version: u32,
    executable: PathBuf,
    version: String,
    directions: Vec<Direction>,
    arguments: Vec<String>,
    kingsoft_wps_native: bool,
}
fn configured_adapter() -> Result<Option<AdapterConfig>, LegacyError> {
    let Some(path) = std::env::var_os("WEFTEXT_LEGACY_OFFICE_ADAPTER") else {
        return Ok(None);
    };
    let path = PathBuf::from(path);
    if !path.is_absolute() {
        return Err(error("adapterConfig", "外部适配配置必须是本机绝对路径"));
    }
    let meta = fs::metadata(&path).map_err(|_| error("adapterConfig", "无法读取外部适配配置"))?;
    if !meta.is_file() || meta.len() > 64 * 1024 {
        return Err(error("adapterConfig", "外部适配配置不是有界普通文件"));
    }
    let config: AdapterConfig = serde_json::from_slice(
        &fs::read(path).map_err(|_| error("adapterConfig", "无法读取外部适配配置"))?,
    )
    .map_err(|_| error("adapterConfig", "外部适配配置格式无效"))?;
    validate_adapter(&config)?;
    Ok(Some(config))
}
fn validate_adapter(config: &AdapterConfig) -> Result<(), LegacyError> {
    if config.schema_version != 1
        || !config.executable.is_absolute()
        || !config.executable.is_file()
        || config.version.trim().is_empty()
        || config.version.len() > 256
        || config.arguments.len() > 64
        || !config.arguments.iter().any(|a| a.contains("{input}"))
        || !config.arguments.iter().any(|a| a.contains("{output}"))
        || config.arguments.iter().any(|a| a.len() > 8192)
    {
        return Err(error(
            "adapterConfig",
            "适配器须声明现存绝对程序路径、版本及输入／输出参数",
        ));
    }
    if config
        .directions
        .iter()
        .any(|d| matches!(d, Direction::WpsToDocx | Direction::DocxToWps))
        && !config.kingsoft_wps_native
    {
        return Err(error(
            "adapterConfig",
            "WPS 方向必须明确声明金山原生格式，不能借用 Microsoft Works 或更改扩展名",
        ));
    }
    Ok(())
}

fn libreoffice() -> Option<PathBuf> {
    if let Some(configured) = std::env::var_os("WEFTEXT_LIBREOFFICE") {
        let path = PathBuf::from(configured);
        return (path.is_absolute() && path.is_file()).then_some(path);
    }
    #[cfg(windows)]
    for root in ["ProgramFiles", "ProgramFiles(x86)"] {
        if let Some(root) = std::env::var_os(root) {
            let path = PathBuf::from(root).join("LibreOffice/program/soffice.com");
            if path.is_file() {
                return Some(path);
            }
        }
    }
    for directory in std::env::split_paths(&std::env::var_os("PATH").unwrap_or_default()) {
        #[cfg(windows)]
        let names = ["soffice.com", "soffice.exe"];
        #[cfg(not(windows))]
        let names = ["soffice", "libreoffice"];
        for name in names {
            let path = directory.join(name);
            if path.is_absolute() && path.is_file() {
                return Some(path);
            }
        }
    }
    None
}

fn command(executable: &Path) -> Command {
    let mut command = Command::new(executable);
    command.stdin(Stdio::null());
    command
}

async fn office_version(executable: &Path) -> Option<String> {
    let output = tokio::time::timeout(
        Duration::from_secs(5),
        command(executable)
            .args(["--headless", "--version"])
            .output(),
    )
    .await
    .ok()?
    .ok()?;
    if !output.status.success() || output.stdout.len() > 4096 || output.stderr.len() > 256 * 1024 {
        return None;
    }
    let text = String::from_utf8_lossy(&output.stdout).trim().to_owned();
    text.starts_with("LibreOffice ").then_some(text)
}

fn writer_filters_present(executable: &Path) -> bool {
    let Ok(executable) = fs::canonicalize(executable) else {
        return false;
    };
    let Some(installation) = executable.parent().and_then(Path::parent) else {
        return false;
    };
    let path = installation.join("share/registry/writer.xcd");
    let Ok(meta) = fs::metadata(&path) else {
        return false;
    };
    if !meta.is_file() || meta.len() > 4 * 1024 * 1024 {
        return false;
    }
    let Ok(registry) = fs::read_to_string(path) else {
        return false;
    };
    registry.contains("oor:name=\"MS Word 97\"")
        && registry.contains("oor:name=\"Office Open XML Text\"")
}

pub(crate) async fn probe() -> LegacyCapabilities {
    let executable = libreoffice();
    let version = if let Some(path) = &executable {
        office_version(path).await
    } else {
        None
    };
    let available = version.is_some()
        && executable
            .as_ref()
            .is_some_and(|path| writer_filters_present(path));
    let directions = [
        Direction::DocToDocx,
        Direction::DocxToDoc,
        Direction::WpsToDocx,
        Direction::DocxToWps,
    ]
    .into_iter()
    .map(|direction| {
        let doc = matches!(direction, Direction::DocToDocx | Direction::DocxToDoc);
        DirectionCapability {
            direction,
            available: available && doc,
            content_roundtrip_verified: false,
            reason: if !doc {
                "内置 LibreOffice 路线不声明金山 .wps；Works 的 .wps 不是同一格式"
            } else if available {
                "可运行本机独立 profile 转换；正文／审阅保留仍须按本次结果核对"
            } else {
                "未同时探测到可运行的 LibreOffice 和 DOC／DOCX Writer 过滤器；可用 WEFTEXT_LIBREOFFICE 指定本机安装程序"
            }
            .into(),
        }
    })
    .collect();
    let mut backends = vec![BackendCapability {
        id: "libreoffice".into(),
        version,
        directions,
    }];
    let configured = configured_adapter();
    let configured_version = configured
        .as_ref()
        .ok()
        .and_then(|c| c.as_ref())
        .map(|c| c.version.clone());
    let directions = [
        Direction::DocToDocx,
        Direction::DocxToDoc,
        Direction::WpsToDocx,
        Direction::DocxToWps,
    ]
    .into_iter()
    .map(|direction| {
        let available = !direction.involves_native_wps() && configured
            .as_ref()
            .ok()
            .and_then(|c| c.as_ref())
            .is_some_and(|c| c.directions.contains(&direction));
        DirectionCapability {
            direction,
            available,
            content_roundtrip_verified: false,
            reason: if direction.involves_native_wps() {
                "当前未实现可证明金山原生 .wps 的格式验证器；配置声明、WPS 已安装及改后缀均不能启用本方向".into()
            } else if available {
                "已配置本机适配器；声明与真实生成内容须单独验收".into()
            } else if let Err(e) = &configured {
                e.message.clone()
            } else {
                "没有为此方向配置已安装的本机原生转换器".into()
            },
        }
    })
    .collect();
    backends.push(BackendCapability {
        id: "configured".into(),
        version: configured_version,
        directions,
    });
    LegacyCapabilities {
        backends,
        ordinary_docx_requires_office: false,
    }
}

fn validate_input(bytes: &[u8], extension: &str) -> Result<(), LegacyError> {
    if bytes.is_empty() || bytes.len() > MAX_BYTES {
        return Err(error("inputSize", "旧格式交换输入须为 1 字节至 64 MiB"));
    }
    match extension {
        "doc" if !bytes.starts_with(OLE_MAGIC) => Err(error(
            "inputFormat",
            "DOC 输入不是支持的 Word 二进制复合文档",
        )),
        "docx" if !bytes.starts_with(b"PK\x03\x04") => {
            Err(error("inputFormat", "中间输入不是 DOCX ZIP 文件"))
        }
        // Unknown WPS input may be retained as exact original bytes. This is
        // size validation only; no native WPS capability follows from it.
        _ => Ok(()),
    }
}

fn validate_native_wps(bytes: &[u8]) -> Result<(), LegacyError> {
    // ZIP member names are stored literally even when member data is deflated.
    // This identifies obvious renamed OOXML, without treating another unknown
    // ZIP container as proof of native Kingsoft WPS support.
    if bytes.starts_with(b"PK")
        && bytes
            .windows(b"word/document.xml".len())
            .any(|w| w == b"word/document.xml")
    {
        return Err(error(
            "wpsRenamedDocx",
            "WPS 输出带有 Word OOXML 主文档标记；不能把 DOCX 改后缀冒充金山原生 WPS",
        ));
    }
    if bytes.starts_with(OLE_MAGIC) {
        let name: Vec<u8> = "WordDocument\0"
            .encode_utf16()
            .flat_map(u16::to_le_bytes)
            .collect();
        // Compound-file directory entries are 128-byte aligned and have a
        // counted UTF-16 name and stream object type. Recognize this obvious
        // Word DOC marker only; no other CFB is presumed to be native WPS.
        if bytes.as_chunks::<128>().0.iter().any(|entry| {
            entry[66] == 2
                && u16::from_le_bytes([entry[64], entry[65]]) as usize == name.len()
                && entry[..name.len()] == name
        }) {
            return Err(error(
                "wpsRenamedDoc",
                "WPS 输出实际带有 WordDocument 二进制 DOC 流；不能改后缀冒充金山原生 WPS",
            ));
        }
    }
    Err(error(
        "nativeWpsUnverified",
        "当前没有可证明金山原生 WPS 的签名／格式验证器；准确字节可以保留，但本方向不提供原生格式成功交付",
    ))
}

fn write_new(path: &Path, bytes: &[u8]) -> Result<(), LegacyError> {
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .map_err(|_| error("preservationFailed", "无法在本次独立目录保留准确文件"))?;
    file.write_all(bytes)
        .and_then(|_| file.sync_all())
        .map_err(|_| error("preservationFailed", "本次准确文件未完整写入"))
}
fn artifact(path: PathBuf, bytes: Vec<u8>) -> Artifact {
    Artifact {
        filename: path
            .file_name()
            .unwrap_or_default()
            .to_string_lossy()
            .into(),
        sha256: format!("{:x}", Sha256::digest(&bytes)),
        length: bytes.len(),
        retained_path: path,
        bytes,
    }
}
fn feature_reports() -> Vec<FeatureReport> {
    [
        (
            "body",
            "外部软件转换正文；未据返回码认定文字、顺序及布局无损",
        ),
        ("images", "图片大小、裁剪、锚定及嵌入保留须核对本次生成物"),
        (
            "formulas",
            "原生公式、可编辑性与对象类型未证明；不能以外观相同代替",
        ),
        ("comments", "批注范围、作者、时间及正文保留未证明"),
        (
            "replies",
            "回复线程关系未证明；不能把普通批注数量当作回复保留",
        ),
        ("resolvedState", "批注解决状态未证明，须在原生宿主核对"),
        (
            "revisions",
            "适配器未调用接受／拒绝修订；外部格式对待审语义的保留未证明，原件始终可取",
        ),
    ]
    .into_iter()
    .map(|(feature, message)| FeatureReport {
        feature: feature.into(),
        before: "retainedInExactOriginal".into(),
        after: "unverified".into(),
        message: message.into(),
    })
    .collect()
}

fn prepare_profile(profile: &Path) -> Result<(), LegacyError> {
    let user = profile.join("user");
    fs::create_dir_all(&user)
        .map_err(|_| error("profileFailed", "无法建立本次独立 Office profile"))?;
    // The paths and properties come from LibreOffice's installed registry
    // schema. They affect only this profile, never the user's Office settings.
    write_new(&user.join("registrymodifications.xcu"), br#"<?xml version="1.0" encoding="UTF-8"?>
<oor:items xmlns:oor="http://openoffice.org/2001/registry">
<item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="DisableMacrosExecution" oor:op="fuse"><value>true</value></prop></item>
<item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="DisableActiveContent" oor:op="fuse"><value>true</value></prop></item>
<item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="BlockUntrustedRefererLinks" oor:op="fuse"><value>true</value></prop></item>
<item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="MacroSecurityLevel" oor:op="fuse"><value>3</value></prop></item>
</oor:items>"#)
}

fn log_excerpt(path: &Path) -> String {
    let Ok(file) = fs::File::open(path) else {
        return String::new();
    };
    let mut bytes = Vec::new();
    let _ = file.take(16 * 1024).read_to_end(&mut bytes);
    String::from_utf8_lossy(&bytes).into()
}

fn save_receipt(result: &ConversionResult) -> Result<(), LegacyError> {
    let receipt = result.workspace.join("result.json");
    write_new(
        &receipt,
        &serde_json::to_vec_pretty(result)
            .map_err(|_| error("receiptFailed", "转换状态无法编码"))?,
    )
}

enum ProcessOutcome {
    Exited(bool),
    Cancelled,
    TimedOut,
    Unknown,
}
async fn run(
    command: &mut Command,
    cancel: &AtomicBool,
    timeout: Duration,
) -> std::io::Result<ProcessOutcome> {
    let mut child = command.spawn().await?;
    let deadline = tokio::time::Instant::now() + timeout;
    let outcome = loop {
        if cancel.load(Ordering::Acquire) {
            break ProcessOutcome::Cancelled;
        }
        if tokio::time::Instant::now() >= deadline {
            break ProcessOutcome::TimedOut;
        }
        match child.try_wait() {
            Ok(Some(status)) => break ProcessOutcome::Exited(status.success()),
            Ok(None) => tokio::time::sleep(Duration::from_millis(75)).await,
            Err(_) => break ProcessOutcome::Unknown,
        }
    };
    if !matches!(outcome, ProcessOutcome::Exited(_)) {
        if child.kill().await.is_err() {
            return Ok(ProcessOutcome::Unknown);
        }
    }
    Ok(outcome)
}

/// `work_root` is supplied by trusted application configuration, not the user
/// request. Callers retain this result under the existing job/request ID and
/// must confirm losses before publishing `generated` bytes. No automatic retry.
#[allow(dead_code)] // Controlled one-shot acceptance API; HTTP consumers use convert_once.
pub(crate) async fn convert(
    request: ConversionRequest,
    work_root: &Path,
    cancel: Arc<AtomicBool>,
) -> Result<ConversionResult, LegacyError> {
    convert_with_timeout(request, work_root, cancel, TIMEOUT).await
}

#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct OnceRequest {
    schema_version: u32,
    request_id: String,
    fingerprint: String,
    backend: String,
    direction: Direction,
    input_sha256: String,
    input_length: usize,
}
#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct OnceCompleted {
    schema_version: u32,
    fingerprint: String,
    result: ConversionResult,
}
fn fingerprint(request: &ConversionRequest) -> String {
    let contract = serde_json::json!({
        "version": 1, "backend": request.backend, "direction": request.direction,
        "sha256": format!("{:x}", Sha256::digest(&request.bytes)), "length": request.bytes.len(),
    });
    format!("{:x}", Sha256::digest(contract.to_string().as_bytes()))
}
fn read_bounded<T: serde::de::DeserializeOwned>(path: &Path) -> Result<T, LegacyError> {
    let meta = fs::symlink_metadata(path).map_err(|_| {
        error(
            "conversionUnknown",
            "原请求记录不完整；保留原操作且不自动重新执行",
        )
    })?;
    if !meta.is_file() || meta.file_type().is_symlink() || meta.len() > 128 * 1024 {
        return Err(error(
            "conversionUnknown",
            "原请求记录无效或超过预算；不自动重新执行",
        ));
    }
    let bytes = fs::read(path)
        .map_err(|_| error("conversionUnknown", "无法读取原请求记录；不自动重新执行"))?;
    serde_json::from_slice(&bytes)
        .map_err(|_| error("conversionUnknown", "原请求记录未完整写入；不自动重新执行"))
}
fn restore_artifact(artifact: &mut Artifact, root: &Path) -> Result<(), LegacyError> {
    let path = fs::canonicalize(&artifact.retained_path).map_err(|_| {
        error(
            "conversionUnknown",
            "原转换工件不可读取；不重新转换或交付新内容",
        )
    })?;
    let meta = fs::symlink_metadata(&artifact.retained_path).map_err(|_| {
        error(
            "conversionUnknown",
            "原转换工件不可读取；不重新转换或交付新内容",
        )
    })?;
    if !path.starts_with(root)
        || !meta.is_file()
        || meta.file_type().is_symlink()
        || artifact.length > MAX_BYTES
        || meta.len() != artifact.length as u64
        || artifact.filename.is_empty()
        || Path::new(&artifact.filename)
            .file_name()
            .is_none_or(|n| n != artifact.filename.as_str())
    {
        return Err(error(
            "conversionUnknown",
            "原转换工件不在原操作边界或长度已变；停止恢复且不重新转换",
        ));
    }
    let bytes = fs::read(&path)
        .map_err(|_| error("conversionUnknown", "原转换工件读取失败；不重新转换"))?;
    if format!("{:x}", Sha256::digest(&bytes)) != artifact.sha256 || bytes.len() != artifact.length
    {
        return Err(error(
            "conversionUnknown",
            "原转换工件内容已变；不交付新内容且不重新转换",
        ));
    }
    artifact.bytes = bytes;
    artifact.retained_path = path;
    Ok(())
}
fn pending_once(
    request: &ConversionRequest,
    request_id: &str,
    workspace: &Path,
) -> Result<ConversionResult, LegacyError> {
    let original_path = workspace.join(format!("original.{}", request.direction.extensions().0));
    let mut original = artifact(original_path, request.bytes.clone());
    restore_artifact(&mut original, workspace)?;
    Ok(ConversionResult {
        request_id: request_id.into(),
        status: "unknown".into(),
        code: "conversionUnknown".into(),
        message: "原请求已登记但没有完整完成回执；准确输入仍保留，请查询原请求，不自动重新执行"
            .into(),
        backend: request.backend.clone(),
        backend_version: None,
        direction: request.direction,
        intermediate_docx: if request.direction.is_import() {
            None
        } else {
            Some(original.clone())
        },
        original,
        generated: None,
        features: feature_reports(),
        workspace: workspace.into(),
        diagnostic: String::new(),
    })
}

/// Persistent once-only wrapper. Reusing an ID only recovers its original
/// outcome; it never launches another process, including after a crash or an
/// incomplete receipt. Callers choose a *new* ID only for an explicit new run.
pub(crate) async fn convert_once(
    request_id: &str,
    request: ConversionRequest,
    work_root: &Path,
    cancel: Arc<AtomicBool>,
) -> Result<ConversionResult, LegacyError> {
    convert_once_mode(request_id, request, work_root, cancel, true).await
}

/// Read-only recovery never creates a directory or starts an external process.
pub(crate) async fn recover_once(
    request_id: &str,
    request: ConversionRequest,
    work_root: &Path,
) -> Result<ConversionResult, LegacyError> {
    convert_once_mode(
        request_id,
        request,
        work_root,
        Arc::new(AtomicBool::new(false)),
        false,
    )
    .await
}

async fn convert_once_mode(
    request_id: &str,
    request: ConversionRequest,
    work_root: &Path,
    cancel: Arc<AtomicBool>,
    allow_start: bool,
) -> Result<ConversionResult, LegacyError> {
    let id = uuid::Uuid::parse_str(request_id)
        .map_err(|_| error("requestId", "旧格式转换需要规范 UUID 操作标识"))?;
    if id.to_string() != request_id || id.get_version() != Some(uuid::Version::Random) {
        return Err(error("requestId", "旧格式转换需要规范 UUIDv4 操作标识"));
    }
    validate_input(&request.bytes, request.direction.extensions().0)?;
    if !work_root.is_absolute() {
        return Err(error("workRoot", "转换恢复目录须为应用拥有的绝对路径"));
    }
    if allow_start {
        fs::create_dir_all(work_root).map_err(|_| error("workRoot", "无法建立转换恢复目录"))?;
    }
    if let Ok(metadata) = fs::symlink_metadata(work_root) {
        let mut redirected = metadata.file_type().is_symlink();
        #[cfg(windows)]
        {
            use std::os::windows::fs::MetadataExt;
            redirected |= metadata.file_attributes() & 0x400 != 0;
        }
        if !metadata.is_dir() || redirected {
            return Err(error("workRoot", "转换恢复目录不是独立普通目录"));
        }
    }
    let root = fs::canonicalize(work_root).map_err(|_| {
        error(
            if allow_start {
                "workRoot"
            } else {
                "conversionNotRegistered"
            },
            "无法确认原转换恢复目录；未启动外部进程",
        )
    })?;
    let workspace = root.join(request_id);
    let fresh = if !allow_start {
        fs::symlink_metadata(&workspace).map_err(|_| {
            error(
                "conversionNotRegistered",
                "原外部转换尚无可读取的操作记录；未启动外部进程",
            )
        })?;
        false
    } else {
        match fs::create_dir(&workspace) {
            Ok(()) => true,
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => false,
            Err(_) => return Err(error("workRoot", "无法分配原操作的独立恢复目录")),
        }
    };
    let meta = fs::symlink_metadata(&workspace)
        .map_err(|_| error("workRoot", "原操作恢复目录无法读取"))?;
    if !meta.is_dir()
        || meta.file_type().is_symlink()
        || fs::canonicalize(&workspace).ok().as_ref() != Some(&workspace)
    {
        return Err(error("workRoot", "原操作恢复目录边界发生变化"));
    }
    let expected = fingerprint(&request);
    if !fresh {
        let original: OnceRequest = read_bounded(&workspace.join("request.json"))?;
        if original.schema_version != 1
            || original.request_id != request_id
            || original.fingerprint != expected
            || original.backend != request.backend
            || original.direction != request.direction
            || original.input_length != request.bytes.len()
            || original.input_sha256 != format!("{:x}", Sha256::digest(&request.bytes))
        {
            return Err(error(
                "requestIdReused",
                "原操作标识已绑定另一份准确输入／后端／方向；拒绝覆盖或重新执行",
            ));
        }
        let completed_path = workspace.join("completed.json");
        if !completed_path.try_exists().unwrap_or(true) {
            return pending_once(&request, request_id, &workspace);
        }
        let mut completed: OnceCompleted = read_bounded(&completed_path)?;
        if completed.schema_version != 1
            || completed.fingerprint != expected
            || completed.result.request_id != request_id
            || completed.result.backend != request.backend
            || completed.result.direction != request.direction
            || !matches!(
                completed.result.status.as_str(),
                "succeeded" | "failed" | "cancelled" | "unknown" | "unavailable"
            )
        {
            return Err(error(
                "conversionUnknown",
                "原操作回执与准确输入不一致；不自动重新执行",
            ));
        }
        let restored_workspace = fs::canonicalize(&completed.result.workspace).map_err(|_| {
            error(
                "conversionUnknown",
                "原转换工作目录不可读取；不自动重新执行",
            )
        })?;
        if !restored_workspace.starts_with(&workspace) {
            return Err(error(
                "conversionUnknown",
                "原转换工作目录超出操作边界；停止恢复",
            ));
        }
        restore_artifact(&mut completed.result.original, &workspace)?;
        if completed.result.original.bytes != request.bytes {
            return Err(error(
                "conversionUnknown",
                "原件与准确输入不一致；停止恢复且不重新执行",
            ));
        }
        if let Some(intermediate) = &mut completed.result.intermediate_docx {
            restore_artifact(intermediate, &workspace)?;
        }
        if let Some(generated) = &mut completed.result.generated {
            restore_artifact(generated, &workspace)?;
        }
        if (completed.result.status == "succeeded") != completed.result.generated.is_some() {
            return Err(error(
                "conversionUnknown",
                "原操作成功状态和准确工件不一致；停止交付",
            ));
        }
        if completed.result.status == "succeeded" && request.direction.involves_native_wps() {
            let bytes = if request.direction.is_import() {
                &completed.result.original.bytes
            } else {
                &completed
                    .result
                    .generated
                    .as_ref()
                    .expect("validated successful receipt")
                    .bytes
            };
            validate_native_wps(bytes)?;
        }
        return Ok(completed.result);
    }
    let input_path = workspace.join(format!("original.{}", request.direction.extensions().0));
    write_new(&input_path, &request.bytes)?;
    let manifest = OnceRequest {
        schema_version: 1,
        request_id: request_id.into(),
        fingerprint: expected.clone(),
        backend: request.backend.clone(),
        direction: request.direction,
        input_sha256: format!("{:x}", Sha256::digest(&request.bytes)),
        input_length: request.bytes.len(),
    };
    write_new(
        &workspace.join("request.json"),
        &serde_json::to_vec(&manifest).map_err(|_| error("receiptFailed", "原操作输入无法编码"))?,
    )?;
    write_new(
        &workspace.join("started.json"),
        b"{\"schemaVersion\":1,\"status\":\"started\"}",
    )?;
    let mut result =
        match convert_in_new_workspace(request.clone(), &workspace, cancel, TIMEOUT, Some("run"))
            .await
        {
            Ok(result) => result,
            Err(e) => {
                let mut result = pending_once(&request, request_id, &workspace)?;
                result.message = format!(
                    "本次转换没有完整完成回执（{}）；保留原操作且不重新执行",
                    e.code
                );
                result
            }
        };
    result.request_id = request_id.into();
    result.original = artifact(input_path, request.bytes);
    if !request.direction.is_import() {
        result.intermediate_docx = Some(result.original.clone());
    }
    write_new(
        &workspace.join("completed.json"),
        &serde_json::to_vec(&serde_json::json!({
            "schemaVersion": 1, "fingerprint": expected, "result": &result,
        }))
        .map_err(|_| {
            error(
                "conversionUnknown",
                "原操作完成回执无法编码；不自动重新执行",
            )
        })?,
    )
    .map_err(|_| {
        error(
            "conversionUnknown",
            "原操作完成回执没有完整持久化；不自动重新执行",
        )
    })?;
    Ok(result)
}

#[allow(dead_code)] // One-shot/timeout acceptance helper, separate from durable HTTP jobs.
async fn convert_with_timeout(
    request: ConversionRequest,
    work_root: &Path,
    cancel: Arc<AtomicBool>,
    timeout: Duration,
) -> Result<ConversionResult, LegacyError> {
    convert_in_new_workspace(request, work_root, cancel, timeout, None).await
}

async fn convert_in_new_workspace(
    request: ConversionRequest,
    work_root: &Path,
    cancel: Arc<AtomicBool>,
    timeout: Duration,
    fixed_name: Option<&str>,
) -> Result<ConversionResult, LegacyError> {
    let (input_ext, output_ext) = request.direction.extensions();
    validate_input(&request.bytes, input_ext)?;
    if !work_root.is_absolute() {
        return Err(error("workRoot", "外部转换工作目录须为应用拥有的绝对路径"));
    }
    fs::create_dir_all(work_root).map_err(|_| error("workRoot", "无法建立外部转换工作目录"))?;
    let request_id = uuid::Uuid::new_v4().to_string();
    let workspace = fs::canonicalize(work_root)
        .map_err(|_| error("workRoot", "无法确认转换工作目录"))?
        .join(fixed_name.unwrap_or(&request_id));
    fs::create_dir(&workspace).map_err(|_| error("workRoot", "无法分配本次独立转换目录"))?;
    let original_path = workspace.join(format!("original.{input_ext}"));
    write_new(&original_path, &request.bytes)?;
    let original = artifact(original_path.clone(), request.bytes);
    let mut result = ConversionResult {
        request_id,
        status: "unavailable".into(),
        code: "backendUnavailable".into(),
        message: String::new(),
        backend: request.backend.clone(),
        backend_version: None,
        direction: request.direction,
        intermediate_docx: if request.direction.is_import() {
            None
        } else {
            Some(original.clone())
        },
        original,
        generated: None,
        features: feature_reports(),
        workspace: workspace.clone(),
        diagnostic: String::new(),
    };
    if cancel.load(Ordering::Acquire) {
        result.status = "cancelled".into();
        result.code = "cancelledBeforeStart".into();
        result.message = "已取消；准确原件已保留，未启动外部转换".into();
        save_receipt(&result)?;
        return Ok(result);
    }
    if let Err(failure) = execution_path_budget(&workspace, &request.backend) {
        result.code = failure.code;
        result.message = failure.message;
        save_receipt(&result)?;
        return Ok(result);
    }
    let output_dir = workspace.join("generated");
    fs::create_dir(&output_dir).map_err(|_| error("workRoot", "无法建立独立输出目录"))?;
    let output_path = output_dir.join(format!("original.{output_ext}"));
    let mut process = match request.backend.as_str() {
        "libreoffice" => {
            if !matches!(
                request.direction,
                Direction::DocToDocx | Direction::DocxToDoc
            ) {
                result.message = "LibreOffice 内置适配不支持金山 .wps；不使用 Microsoft Works 过滤器或更改扩展名".into();
                save_receipt(&result)?;
                return Ok(result);
            }
            let Some(executable) = libreoffice() else {
                result.message = "本机未找到 LibreOffice；普通 DOCX 功能仍可使用".into();
                save_receipt(&result)?;
                return Ok(result);
            };
            result.backend_version = office_version(&executable).await;
            if result.backend_version.is_none() {
                result.message = "本机 LibreOffice 版本探测失败；没有启动转换".into();
                save_receipt(&result)?;
                return Ok(result);
            }
            if !writer_filters_present(&executable) {
                result.message =
                    "发现 LibreOffice 版本但没有确认 DOC／DOCX Writer 过滤器；此方向不可用".into();
                save_receipt(&result)?;
                return Ok(result);
            }
            // Real 26.2.6.3 DOC-chain readback retained pending insertion and
            // deletion text/author but rounded timestamps to minutes and
            // flattened a reply into a separate ordinary comment. Keep those
            // observed losses visible without claiming this input was fully
            // inspected or that another host/version behaves identically.
            if result
                .backend_version
                .as_deref()
                .is_some_and(|v| v.starts_with("LibreOffice 26.2.6.3 "))
            {
                for feature in &mut result.features {
                    match feature.feature.as_str() {
                        "comments" => feature.message = "此版本 DOC 链路实测批注时间精度降到分钟；本次范围、作者及正文保留仍须核对".into(),
                        "replies" => feature.message = "此版本 DOC 链路实测回复退为独立普通批注；不承诺回复线程保留，原件中的关系仍可取".into(),
                        "resolvedState" => feature.message = "此版本 DOC 链路实测扩展批注线程部件丢失；解决状态未证明保留，须核对原件".into(),
                        "revisions" => feature.message = "此版本 DOC 链路实测待审插入／删除及作者保留但时间精度降到分钟；适配器未调用接受／拒绝，本次其余待审语义仍须核对".into(),
                        _ => {}
                    }
                }
            }
            let profile = workspace.join("profile");
            prepare_profile(&profile)?;
            let url = url::Url::from_directory_path(&profile)
                .map_err(|_| error("workRoot", "独立 Office profile 地址无效"))?;
            let mut process = command(&executable);
            process
                .arg(format!("-env:UserInstallation={url}"))
                .args([
                    "--headless",
                    "--nologo",
                    "--nodefault",
                    "--norestore",
                    "--nofirststartwizard",
                    "--convert-to",
                ])
                .arg(if output_ext == "docx" {
                    "docx:Office Open XML Text"
                } else {
                    "doc:MS Word 97"
                })
                .arg("--outdir")
                .arg(&output_dir)
                .arg(&original_path);
            process
        }
        "configured" => {
            if request.direction.involves_native_wps() {
                result.code = "nativeWpsUnverified".into();
                result.message = "当前没有可证明金山原生 WPS 的格式验证器；未启动配置适配器，不能以声明或改后缀认定此方向可用".into();
                save_receipt(&result)?;
                return Ok(result);
            }
            let config = match configured_adapter() {
                Ok(Some(config)) if config.directions.contains(&request.direction) => config,
                Ok(_) => {
                    result.message = "本机没有配置此方向的原生旧格式转换器".into();
                    save_receipt(&result)?;
                    return Ok(result);
                }
                Err(e) => {
                    result.code = e.code;
                    result.message = e.message;
                    save_receipt(&result)?;
                    return Ok(result);
                }
            };
            result.backend_version = Some(config.version.clone());
            let mut process = command(&config.executable);
            let direction = serde_json::to_value(request.direction).unwrap_or_default();
            for argument in config.arguments {
                process.arg(
                    argument
                        .replace("{input}", &original_path.to_string_lossy())
                        .replace("{output}", &output_path.to_string_lossy())
                        .replace("{direction}", direction.as_str().unwrap_or_default())
                        .replace("{workspace}", &workspace.to_string_lossy()),
                );
            }
            process
        }
        _ => {
            result.code = "backendUnsupported".into();
            result.message = "请选择已探测的外部软件后端".into();
            save_receipt(&result)?;
            return Ok(result);
        }
    };
    let log_path = workspace.join("converter.log");
    let log = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&log_path)
        .map_err(|_| error("workRoot", "无法建立本次转换日志"))?;
    let stderr = log
        .try_clone()
        .map_err(|_| error("workRoot", "无法建立转换诊断输出"))?;
    process
        .current_dir(&workspace)
        .stdout(Stdio::from(log))
        .stderr(Stdio::from(stderr));
    let outcome = run(&mut process, &cancel, timeout).await;
    result.diagnostic = log_excerpt(&log_path);
    let completed = match outcome {
        Ok(ProcessOutcome::Exited(true)) if !cancel.load(Ordering::Acquire) => true,
        Ok(ProcessOutcome::Cancelled) | Ok(ProcessOutcome::Exited(_))
            if cancel.load(Ordering::Acquire) =>
        {
            result.status = "cancelled".into();
            result.code = "conversionCancelled".into();
            result.message = "已停止本次转换；原件已保留，迟到输出未作为成功产物交付".into();
            false
        }
        Ok(ProcessOutcome::TimedOut) => {
            result.status = "failed".into();
            result.code = "conversionTimeout".into();
            result.message = "本次独立转换超时；原件及工作目录保留，未交付未确认产物".into();
            false
        }
        Ok(ProcessOutcome::Unknown) => {
            result.status = "unknown".into();
            result.code = "conversionUnknown".into();
            result.message = "无法确认原转换进程结果；保留原请求与工作目录，不自动重新执行".into();
            false
        }
        Ok(ProcessOutcome::Exited(false)) | Ok(ProcessOutcome::Cancelled) => {
            result.status = "failed".into();
            result.code = "conversionFailed".into();
            result.message = "外部软件未完成本次转换；准确原件已保留".into();
            false
        }
        Ok(ProcessOutcome::Exited(true)) => {
            result.status = "cancelled".into();
            result.code = "conversionCancelled".into();
            result.message = "转换完成与取消请求相交；保留原件与工作目录，没有交付迟到结果".into();
            false
        }
        Err(_) => {
            result.status = "failed".into();
            result.code = "conversionStartFailed".into();
            result.message = "无法安全启动／隔离外部转换；准确原件已保留".into();
            false
        }
    };
    // A configured tool is not allowed to replace the preserved preimage.
    // Preserve a fresh copy if it touched its input and reject its output.
    if fs::read(&original_path).ok().as_deref() != Some(result.original.bytes.as_slice()) {
        let preserved_path = workspace.join(format!("preserved-original.{input_ext}"));
        write_new(&preserved_path, &result.original.bytes)?;
        result.original.retained_path = preserved_path;
        if !request.direction.is_import() {
            result.intermediate_docx = Some(result.original.clone());
        }
        result.status = "failed".into();
        result.code = "converterChangedInput".into();
        result.message = "外部转换器改写了输入副本；准确原件已另行保留，本次输出没有交付".into();
        save_receipt(&result)?;
        return Ok(result);
    }
    if completed {
        match read_generated(&output_path, output_ext, &workspace) {
            Ok(bytes) => {
                let generated = artifact(output_path, bytes);
                if request.direction.is_import() {
                    result.intermediate_docx = Some(generated.clone())
                }
                result.generated = Some(generated);
                result.status = "succeeded".into();
                result.code = "generatedWithUnverifiedLosses".into();
                result.message = "已生成并冻结准确文件；逐项损失尚未证明，确认后才可继续导入／交付。原件与中间 DOCX 已保留".into();
            }
            Err(e) => {
                result.status = "failed".into();
                result.code = e.code;
                result.message = e.message;
            }
        }
    }
    save_receipt(&result)?;
    Ok(result)
}

fn read_generated(path: &Path, extension: &str, workspace: &Path) -> Result<Vec<u8>, LegacyError> {
    let meta = fs::symlink_metadata(path).map_err(|_| {
        error(
            "outputMissing",
            "外部程序没有产生本次预期文件；未把返回码当作成功",
        )
    })?;
    if !meta.is_file()
        || meta.file_type().is_symlink()
        || meta.len() == 0
        || meta.len() > MAX_BYTES as u64
    {
        return Err(error("outputInvalid", "本次输出不是有界普通文件；未交付"));
    }
    let resolved = fs::canonicalize(path)
        .map_err(|_| error("outputInvalid", "无法确认本次输出的独立目录边界"))?;
    let workspace = fs::canonicalize(workspace)
        .map_err(|_| error("outputInvalid", "本次转换工作目录无法确认"))?;
    if !resolved.starts_with(&workspace) {
        return Err(error(
            "outputInvalid",
            "本次输出超出原操作的独立工作目录；未交付",
        ));
    }
    let bytes = fs::read(path)
        .map_err(|_| error("outputReadFailed", "无法冻结本次准确输出；工作目录仍保留"))?;
    if extension == "wps" {
        validate_native_wps(&bytes)?;
    }
    validate_input(&bytes, extension).map_err(|_| {
        error(
            "outputFormat",
            "本次输出内容与声明格式不一致；不能仅改扩展名",
        )
    })?;
    Ok(bytes)
}

