    #[test]
    fn flat_scoped_ids_preserve_actor_epoch_library_purpose_and_original_operation_isolation() {
        let temp = tempfile::tempdir().unwrap();
        let library = temp.path().join("library");
        let id = uuid::Uuid::new_v4().to_string();
        let derive = |deployment, root: &Path, actor, epoch, purpose| {
            scoped_location(temp.path(), deployment, root, actor, epoch, &id, purpose).unwrap()
        };
        let location = derive("deploy", &library, "alice", 3, "export");
        assert_eq!(location.root, temp.path().join("runs"));
        assert_eq!(
            location.request_id,
            derive("deploy", &library, "alice", 3, "export").request_id
        );
        assert_eq!(
            uuid::Uuid::parse_str(&location.request_id)
                .unwrap()
                .get_version(),
            Some(uuid::Version::Random)
        );
        for other in [
            derive("other", &library, "alice", 3, "export"),
            derive("deploy", &temp.path().join("other"), "alice", 3, "export"),
            derive("deploy", &library, "bob", 3, "export"),
            derive("deploy", &library, "alice", 4, "export"),
            derive("deploy", &library, "alice", 3, "import"),
        ] {
            assert_eq!(location.root, other.root);
            assert_ne!(location.request_id, other.request_id);
        }
        let next = scoped_location(
            temp.path(),
            "deploy",
            &library,
            "alice",
            3,
            &uuid::Uuid::new_v4().to_string(),
            "export",
        )
        .unwrap();
        assert_ne!(location.request_id, next.request_id);
        assert!(!location.root.exists());
    }

